-- Cassandra schema for user timelines (fan-out on write)
CREATE TABLE user_feed (
  user_id BIGINT,
  post_id BIGINT,
  post_timestamp TIMESTAMP,
  author_id BIGINT,

  PRIMARY KEY (user_id, post_timestamp, post_id)
) WITH CLUSTERING ORDER BY (post_timestamp DESC);

-- Enables efficient query: SELECT * FROM user_feed WHERE user_id = ? LIMIT 50;
-- Pre-computed feed for fast reads
